class AstarJps(Spsp):
    REQUIRES = frozenset({COST})

    @override
    def __init__(self, ctx: PrecompCtx) -> None:
        self.w = ctx.w
        stride = ctx.w + 1
        n_pad = stride * (ctx.h + 1)
        cost_pad = [INF] * n_pad
        cost = ctx[COST]
        for y in range(ctx.h):
            for x in range(ctx.w):
                cost_pad[y * stride + x] = cost[y * ctx.w + x]
        self.stride = stride
        self.n_pad = n_pad
        self.cost_pad = cost_pad

    @override
    def plan(self, start: int, goal: int) -> Path_:
        w = self.w
        sp = (start // w) * self.stride + (start % w)
        gp = (goal // w) * self.stride + (goal % w)
        return astar_jps(self.stride, self.n_pad, self.cost_pad, sp, gp, w)
